<script setup lang="ts">import {ref,computed,watch} from 'vue';import {useRoute} from 'vue-router';import {useResearchData} from '../hooks/useResearch';import {useAuth} from '../stores/auth';import {useAction} from '../hooks/useAction';import {annotateSample} from '../api/samples';import {getPhaseProgress} from '../api/phases';import {PhaseProgress} from '../types/domain';import StudySelector from '../components/StudySelector.vue';import CompositionMatrix from '../components/CompositionMatrix.vue';import DataTable from '../components/common/DataTable.vue';import Notice from '../components/common/Notice.vue';import {VersionStatus} from '../constants/enums';const s=useResearchData(),auth=useAuth(),a=useAction(),route=useRoute(),id=ref(Number(route.query.study)||0),selected=ref(0),note=ref(''),progress=ref<PhaseProgress|null>(null),versionId=ref<number|null>(null);const study=computed(()=>s.studies.find(x=>x.id===id.value)||s.studies[0]),sample=computed(()=>s.samples.find(x=>x.id===selected.value)||s.samples[0]);const viewable=computed(()=>s.versions.filter(v=>v.status!=='invalidated'));const shown=computed(()=>s.versions.find(v=>v.id===versionId.value)||s.versions.find(v=>v.status==='active')||s.versions[0]);async function load(){if(!study.value)return;if(versionId.value===null){const p=await getPhaseProgress(study.value.id).catch(()=>null);progress.value=p;versionId.value=p?.active_version?.id??null}await s.loadStudy(study.value.id,versionId.value??undefined)}watch(()=>study.value?.id,()=>{versionId.value=null;selected.value=0;load()},{immediate:true});watch(versionId,load);watch(()=>sample.value,()=>note.value=sample.value?.note||'');function save(){a.execute(async()=>{await annotateSample(sample.value.id,note.value);await load()})}</script><template><div class="page"><div class="page-title"><div><p class="eyebrow">PHASE SOURCES / 02</p><h1>相份额来源<span>原相对量、组规模与零值口径一起核对。</span></h1></div></div><Notice :message="s.error||a.error.value" @retry="load"/><StudySelector :studies="s.studies" :model-value="study?.id||0" @update:model-value="id=$event"/><div v-if="study" :class="['source-note',!study.supported?'warning':'']"><b>{{study.reason}}</b><p>{{study.description}}</p><small>{{study.source}} · {{Object.entries(study.group_counts).map(([g,n])=>g+' '+n).join(' / ')}}</small></div><div v-if="progress" class="version-strip" aria-label="相通道版本与迁移进度"><div><span class="eyebrow">ACTIVE PHASE VERSION</span><b v-if="progress.active_version">v{{progress.active_version.version}} / {{progress.active_version.label}}</b><b v-else>尚无版本</b><small>{{progress.version_count}} 个版本 · 当前页读取所选版本通道</small><label class="inline-select">查看版本<select aria-label="查看相通道版本" v-model.number="versionId"><option v-for="v in viewable" :key="v.id" :value="v.id">v{{v.version}} / {{v.label}} · {{VersionStatus[v.status]}}</option></select></label></div><div class="version-progress"><span class="eyebrow">MIGRATION PROGRESS</span><template v-if="progress.in_progress_progress.length"><p v-for="m in progress.in_progress_progress" :key="m.migration_id">#{{m.migration_id}} {{m.label}} · 已确认 {{m.progress.confirmed}}/{{m.progress.total}} · 和值不符 {{m.progress.mismatch}} · 待补录 {{m.progress.pending}}</p><RouterLink to="/migrate">继续补录 →</RouterLink></template><p v-else>没有进行中的迁移。<RouterLink to="/migrate">发起相通道拆分 →</RouterLink></p></div></div><div class="section-heading"><h2>固定相通道</h2><span>互斥分析相 / 不解释绝对产量</span></div><DataTable :head="['次序','相通道','单位','口径','版本']"><tr v-for="c in s.components" :key="c.id"><td>{{c.position+1}}</td><td>{{c.label}}</td><td>{{c.unit}}</td><td>{{c.meaning}}</td><td><small>v{{shown?.version??'—'}} {{shown?VersionStatus[shown.status]:''}}</small></td></tr></DataTable><div class="source-grid"><section><div class="section-heading"><h2>原始样本矩阵</h2><span>{{s.samples.length}}样本 / 点击一行批注</span></div><CompositionMatrix :components="s.components" :samples="s.samples" :selected="sample?.id" @select="selected=$event"/></section><aside class="sample-reading"><span class="eyebrow">SELECTED SAMPLE</span><h2>{{sample?.code}}</h2><p>{{sample?.group}} / {{sample?.zero_count}}个零<br/>零按未检出通道处理，不静默加伪计数。</p><p v-if="shown" class="version-caption">{{VersionStatus[shown.status]}}版本 v{{shown.version}}：{{shown.label}}。{{shown.status==='retired'?'旧版仍可分析，历史结果与获批导出保留其旧相依据。':'当前版本用于新研究快照。'}}</p><label>样本批注<textarea aria-label="样本批注" v-model="note" :disabled="auth.user?.role==='viewer'"/></label><button v-if="auth.user?.role!=='viewer'" class="outline" :disabled="a.busy.value||note.length<8||!sample" @click="save">保存批注</button><small>数值与分组只读；后续运行冻结批注，历史运行不回写。拆分后的样本原量已冻结在对应版本中。</small></aside></div></div></template>
